 184	\begin{definition}[Consistent strategies]\label{def:consistent-strategy}
 185		\lean{MIPStarRE.QPBT.IsConsistentStrategyOn, MIPStarRE.QPBT.SymmetricStrategy.IsConsistent}
 186		\leanok
 187		\uses{def:consistent-measurement, def:projective-strategy-general}
 188		Let $\mathcal S = (\ket{\psi}, A, B)$ be a projective strategy with state $\ket{\psi} \in \mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, defined on question alphabets $\mathcal X$ and $\mathcal Y$ and answer alphabets $\mathcal A$ and $\mathcal B$, respectively. We say that $\mathcal S$ is \emph{consistent} if for all $x \in \mathcal X$ the measurement $\{A^x_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$, and for all $y \in \mathcal Y$ the measurement $\{B^y_b\}_{b \in \mathcal B}$ is consistent on $\ket{\psi}$.
 189	\end{definition}
 190	
 191	We almost always restrict attention to symmetric strategies; in this case consistency implies that whenever both players are sent the same question, they provide the same answer.
